+// newTraverseGenericFunc creates a new traverseFunc for nodes with 4, 16, or 256 children.
+// The reverse parameter indicates whether to traverse the children in reverse order.
+func newTraverseGenericFunc(numChildren int, reverse bool) traverseFunc {
+	ctx := &traverseContext{
+		numChildren:   numChildren,
+		zeroChildDone: false,
+		curChildIdx:   ternary(reverse, numChildren-1, 0),
+	}
+
+	return ternary(reverse, ctx.descTraversal, ctx.ascTraversal)
+}
+
+// traverse48Context is a context for traversing nodes with 48 children.
+type traverse48Context struct {
+	curKeyIdx     int
+	curKeyCh      byte
+	zeroChildDone bool
+	n48           *node48
+}
+
+// ascTraversal traverses the children in ascending order.
+func (ctx *traverse48Context) ascTraversal() (int, bool) {
+	if !ctx.zeroChildDone {
+		ctx.zeroChildDone = true
+
+		return node48Max, true
+	}
+
+	for ; ctx.curKeyIdx < node256Max; ctx.curKeyIdx++ {
+		if ctx.n48.hasChild(ctx.curKeyIdx) {
+			ctx.curKeyCh = ctx.n48.keys[ctx.curKeyIdx]
+			ctx.curKeyIdx++
+
+			return int(ctx.curKeyCh), true
+		}
+	}
+
+	return 0, false
+}
+
+// descTraversal traverses the children in descending order.
+func (ctx *traverse48Context) descTraversal() (int, bool) {
+	for ; ctx.curKeyIdx > 0; ctx.curKeyIdx-- {
+		if ctx.n48.hasChild(ctx.curKeyIdx) {
+			ctx.curKeyCh = ctx.n48.keys[ctx.curKeyIdx]
+			ctx.curKeyIdx--
+
+			return int(ctx.curKeyCh), true
+		}
+	}
+
+	if !ctx.zeroChildDone {
+		ctx.zeroChildDone = true
+
+		return node48Max, true
+	}
+
+	return 0, false
+}
+
+// newTraverse48Func creates a new traverseFunc for nodes with 48 children.
+// The reverse parameter indicates whether to traverse the children in reverse order.
+func newTraverse48Func(n48 *node48, reverse bool) traverseFunc {
+	ctx := &traverse48Context{
+		curKeyIdx: ternary(reverse, node256Max-1, 0),
+		n48:       n48,
+	}
+
+	return ternary(reverse, ctx.descTraversal, ctx.ascTraversal)
+}
+
+// forEachRecursively recursively traverses the tree and calls the callback function.
+// It returns traverseStop if the callback function returns false, otherwise traverseContinue.
+func (tr *tree) forEachRecursively(current *nodeRef, callback Callback, reverse bool) traverseAction {
+	if current == nil {
+		return traverseContinue
+	}
+
+	if !callback(current) {
+		return traverseStop
+	}
+
+	nextFn := newTraverseFunc(current, reverse)
+	children := toNode(current).allChildren()
+
+	return tr.traverseChildren(nextFn, children, callback, reverse)
+}
+
+// traverseChildren traverses the children of a node and calls the callback function.
+// It returns traverseStop if the callback function returns false, otherwise traverseContinue.
+func (tr *tree) traverseChildren(nextFn traverseFunc, children []*nodeRef, cb Callback, reverse bool) traverseAction {
+	for {
+		idx, hasMore := nextFn()
+		if !hasMore {
+			break
+		}
+
+		if child := children[idx]; child != nil {
+			if tr.forEachRecursively(child, cb, reverse) == traverseStop {
+				return traverseStop
+			}
+		}
+	}
+
+	return traverseContinue
+}
+
+// forEachPrefix recursively traverses the tree with the given prefix and calls the callback function.
+// It returns traverseStop if the callback function returns false, otherwise traverseContinue.
+func (tr *tree) forEachPrefix(key Key, callback Callback, opts int) traverseAction {
+	opts &= (TraverseLeaf | TraverseReverse) // keep only leaf and reverse options
+	
+	// Navigate to the node that matches the prefix
+	keyOffset := 0
+	current := tr.root
+	
+	// Follow the prefix down the tree
+	for current != nil && keyOffset < len(key) {
+		if current.isLeaf() {
+			// We reached a leaf, check if it matches the prefix
+			leaf := current.leaf()
+			if leaf.prefixMatch(key) {
+				// Call callback on this leaf
+				if !callback(current) {
+					return traverseStop
+				}
+			}
+			return traverseContinue
+		}
+
+		curNode := current.node()
+		
+		// Check node's prefix
+		if curNode.prefixLen > 0 {
+			prefixLen := minInt(int(curNode.prefixLen), len(key)-keyOffset)
+			nodePrefix := curNode.prefix[:prefixLen]
+			keyPrefix := key[keyOffset : keyOffset+prefixLen]
+			
+			// Compare prefixes
+			matchLen := 0
+			for i := 0; i < prefixLen && i < len(nodePrefix); i++ {
+				if nodePrefix[i] == keyPrefix[i] {
+					matchLen++
+				} else {
+					break
+				}
+			}
+			
+			// If prefixes don't fully match, no need to continue
+			if matchLen < prefixLen {
+				// Check if node prefix is a prefix of key prefix
+				if matchLen == len(nodePrefix) && matchLen < prefixLen {
+					// Node prefix is shorter, continue to children
+				} else {
+					// No match, stop traversal
+					return traverseContinue
+				}
+			}
+			
+			// If we've consumed the entire key, we found the prefix node
+			if keyOffset+matchLen >= len(key) {
+				// Traverse subtree rooted at current node
+				return tr.forEachRecursively(current, callback, opts&TraverseReverse == TraverseReverse)
+			}
+			
+			keyOffset += matchLen
+		}
+		
+		// Move to the appropriate child
+		next := current.findChildByKey(key, keyOffset)
+		if *next != nil {
+			current = *next
+			keyOffset++
+		} else {
+			// No child for this key, stop traversal
+			current = nil
+		}
+	}
+	
+	// If we've consumed the entire key, traverse the subtree
+	if keyOffset >= len(key) && current != nil {
+		return tr.forEachRecursively(current, callback, opts&TraverseReverse == TraverseReverse)
+	}
+	
+	return traverseContinue
+}
